package com.maviinamane.delivery;
import java.math.BigDecimal; import java.util.List; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration public class DeliveryChargeSeedConfig{@Bean CommandLineRunner seedDeliveryCharges(DeliveryChargeConfigRepository r){return args->{if(r.count()>0)return;r.saveAll(List.of(s("DISTANCE",0,5,30),s("DISTANCE",5,10,50),s("DISTANCE",10,15,70),s("DISTANCE",15,20,100),s("DISTANCE",20,null,150),s("WEIGHT",0,5,0),s("WEIGHT",5,10,20),s("WEIGHT",10,15,40),s("WEIGHT",15,20,60),s("WEIGHT",20,null,80)));};}private DeliveryChargeConfig s(String t,double min,Number max,double c){var v=new DeliveryChargeConfig();v.setType(t);v.setMinValue(BigDecimal.valueOf(min));v.setMaxValue(max==null?null:BigDecimal.valueOf(max.doubleValue()));v.setCharge(BigDecimal.valueOf(c));return v;}}
